import sys

def solve(text, queries):
    n = len(text)
    if not text: return "\n".join(["0"] * len(queries))

    # Build Suffix Array in O(N log N) or O(N log^2 N)
    sa = list(range(n))
    rank = [ord(c) for c in text]
    k = 1
    while k < n:
        # Sort suffixes based on (rank[i], rank[i+k] if exists else -1)
        def get_rank(i):
            return (rank[i], rank[i+k] if i+k < n else -1)
        sa.sort(key=get_rank)

        new_rank = [0] * n
        for i in range(1, n):
            new_rank[sa[i]] = new_rank[sa[i-1]] + (1 if get_rank(sa[i]) > get_rank(sa[i-1]) else 0)
        rank = new_rank
        if rank[sa[n-1]] == n - 1: break
        k *= 2

    def count_occurrences(p):
        m = len(p)
        # Binary search for range [l, r] in sa
        # Left bound
        low, high = 0, n - 1
        l_idx = n
        while low <= high:
            mid = (low + high) // 2
            if text[sa[mid]:sa[mid]+m] >= p:
                l_idx = mid
                high = mid - 1
            else:
                low = mid + 1

        # Right bound
        low, high = 0, n - 1
        r_idx = -1
        while low <= high:
            mid = (low + high) // 2
            if text[sa[mid]:sa[mid]+m] <= p:
                r_idx = mid
                low = mid + 1
            else:
                high = mid - 1

        if l_idx <= r_idx: return r_idx - l_idx + 1
        return 0

    return "\n".join([str(count_occurrences(q)) for q in queries])

if __name__ == '__main__':
    lines = sys.stdin.read().splitlines()
    if not lines: sys.exit(0)
    text = lines[0].strip()
    q_count = int(lines[1].strip()) if len(lines) > 1 else 0
    queries = [lines[i+2].strip() for i in range(q_count)]
    print(solve(text, queries))

